func pipelangFoldValidCaseText(value string) string {
	var folded strings.Builder
	folded.Grow(len(value))
	for _, scalar := range value {
		if replacement, ok := pipelangCaseFolding17[scalar]; ok {
			folded.WriteString(replacement)
		} else {
			folded.WriteRune(scalar)
		}
	}
	return folded.String()
}

func pipelangContainsCaseFoldedText(value, query string) bool {
	pipelangValidateText(value)
	pipelangValidateText(query)
	return strings.Contains(pipelangFoldValidCaseText(value), pipelangFoldValidCaseText(query))
}

